// Collapse topic groups belonging to the same textbook while retaining their section labels.
for (const subject of Object.keys(curriculum)) {
  const grouped = new Map();
  for (const part of curriculum[subject]) {
    const split = part.unit.split(/\s*·\s*/);
    const book = split[0];
    const section = split.slice(1).join(' · ') || '综合';
    if (!grouped.has(book)) grouped.set(book,{unit:book,lessons:[]});
    for (const lesson of part.lessons) grouped.get(book).lessons.push({...lesson,section});
  }
  curriculum[subject] = [...grouped.values()];
}
// Merge repeated topic names while preserving all distinct knowledge points.
for(const subject of Object.keys(curriculum))for(const book of curriculum[subject]){const seen=new Map();for(const lesson of book.lessons){if(!seen.has(lesson.name))seen.set(lesson.name,lesson);else{const existing=seen.get(lesson.name);const extra=lesson.items.filter(x=>!existing.items.some(y=>y[0]===x[0]));if(extra.length){let n=2;let name=lesson.name+' · 进阶';while(seen.has(name))name=lesson.name+' · 进阶 '+n++;seen.set(name,{...lesson,name})}}}book.lessons=[...seen.values()]}
