for(const [subject,books] of Object.entries(curriculum)){books.sort((a,b)=>bookOrder[subject].indexOf(a.unit)-bookOrder[subject].indexOf(b.unit));for(const book of books){const order=lessonOrder[book.unit]||[];book.lessons.sort((a,b)=>{let x=order.indexOf(a.name),y=order.indexOf(b.name);return (x<0?999:x)-(y<0?999:y)})}}
